import sys, json

# The apply tool: the SECOND tool call of the same requester, and the reason the
# builder never needs an edge to the mutation door. It carries the manifest and
# its digest back out of this hive under the caller's own identity.
doc = json.load(sys.stdin)
env = doc["envelope"]
hop = (env.get("header") or {}).get("hop") or {}
ctx = (env.get("header") or {}).get("context") or {}
body = doc["body"]

if hop.get("route") == "in_build_result":
    # ---- Phase B: the receipt.
    call_id = str(ctx.get("build_call_id") or hop.get("tool_call_id") or "")
    header = {"operation": "apply", "tool_call_id": call_id}
    if hop.get("error_code"):
        header["error_code"] = str(hop["error_code"])
    for key in ("applied", "failed_at", "remaining"):
        if hop.get(key) is not None:
            header[key] = hop[key]
    said = ""
    for m in (body.get("messages") or []):
        if m.get("text"):
            said = str(m["text"])
    if hop.get("error_code"):
        # NAME the code in the turn. The model only sees the turn, and a
        # refusal it cannot name is one it cannot explain to the human who
        # asked -- nor decide what to do about.
        text = "the submission was refused: %s" % hop["error_code"]
        if said:
            text += " -- " + said[:600]
    elif said:
        text = said
    else:
        text = "the submission came back without a sentence"
    sys.stdout.write(json.dumps({
        "header": header,
        "messages": [{"origin": "tool", "type": "tool_result", "id": call_id,
                      "text": text}]}))
    sys.exit(0)

# ---- Phase A: the second tool call. The manifest and its digest come back
# through the chat verbatim -- they were shown to a human, and the digest is
# what makes "verbatim" checkable rather than hoped for. This cell does NOT
# re-render, re-order or re-serialise them: any of those changes the bytes and
# the submitter would refuse its own colony's draft.
call_id = str(hop.get("tool_call_id") or "")
raw_args = ""
for m in (body.get("messages") or []):
    if m.get("type") == "tool_call" and m.get("text"):
        raw_args = m["text"]
try:
    args = json.loads(raw_args)
    if not isinstance(args, dict):
        args = {}
except Exception:
    args = {}

manifest = args.get("manifest")
if not isinstance(manifest, list) or not manifest:
    # A call without a manifest has nothing to do at the OS level, and the
    # answer belongs in the same round.
    sys.stdout.write(json.dumps({
        "header": {"operation": "apply", "error_code": "manifest_missing",
                   "tool_call_id": call_id},
        "messages": [{"origin": "tool", "type": "tool_result", "id": call_id,
            "text": "apply_manifest needs the manifest list from the draft, verbatim"}]}))
    sys.exit(0)

sys.stdout.write(json.dumps({
    "header": {"operation": "apply_request", "build_op": "apply",
               "tool_call_id": call_id,
               "manifest_sha256": str(args.get("manifest_sha256") or "")},
    "manifest": manifest,
    "messages": []}))
